const rows = $input
  .all()
  .map(item => item.json ?? {});

function cleanText(value) {
  return String(value ?? '').trim();
}

function upper(value) {
  return cleanText(value).toUpperCase();
}

function toNumber(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

const applicationStatusOrder = {
  TO_REVIEW: 1,
  APPLY: 2,
  APPLIED: 3,
  SKIPPED: 9,
};

const opportunities = rows
  .filter(row => {
    const opportunityKey =
      cleanText(row.opportunity_key);

    return (
      opportunityKey &&
      !opportunityKey.startsWith('test::')
    );
  })
  .map(row => {
    const applicationStatus =
      upper(row.application_status);

    const outreachMode =
      upper(row.outreach_mode);

    const opportunityType =
      upper(row.opportunity_type) ||
      'DIRECT_APPLICATION';

    const outreachApproval =
      upper(row.outreach_approval);

    const outreachStatus =
      upper(row.outreach_status);

    const draftFinalStatus =
      upper(row.draft_final_status);

    const emailConfidence =
      upper(row.contact_email_confidence);

    const contactEmail =
      cleanText(row.contact_email);

    const sentAt =
      cleanText(row.sent_at);

    const outreachEligible =
      applicationStatus === 'APPLIED' ||
      ['ADJACENT_ROLE', 'SPECULATIVE'].includes(
      outreachMode
    );

    const canSendEmail =
      outreachEligible &&
      outreachApproval === 'APPROVED' &&
      outreachStatus === 'DRAFT_READY' &&
      draftFinalStatus === 'READY' &&
      ['HIGH', 'MEDIUM','USER_VERIFIED',].includes(
        emailConfidence
      ) &&
      Boolean(contactEmail) &&
      !sentAt;

    return {
      opportunity_key:
        cleanText(row.opportunity_key),

      company_key:
        cleanText(row.company_key),

      company_name:
        cleanText(row.company_name),

      company_domain:
        cleanText(row.company_domain),

      country:
        cleanText(row.country),

      position_title:
        cleanText(row.position_title),

      vacancy_url:
        cleanText(row.vacancy_url),

      qualification_score:
        toNumber(row.qualification_score),

      qualification_reason:
        cleanText(row.qualification_reason),

      visa_support_status:
        cleanText(row.visa_support_status),

      outreach_angle:
        cleanText(row.outreach_angle),

      application_status:
        applicationStatus || 'TO_REVIEW',

      applied_at:
        cleanText(row.applied_at),

      contact_research_status:
        upper(row.contact_research_status),

      manual_contact_status:
        upper(row.manual_contact_status),

      contact_source:
        upper(row.contact_source),

      contact_name:
        cleanText(row.contact_name),

      contact_role:
        cleanText(row.contact_role),

      contact_email:
        contactEmail,

      contact_email_confidence:
        emailConfidence,

      contact_linkedin_url:
        cleanText(row.contact_linkedin_url),

      outreach_channel:
        upper(row.outreach_channel),

      outreach_approval:
        outreachApproval || 'PENDING',

      outreach_status:
        outreachStatus || 'NOT_STARTED',

      outreach_mode:
        outreachMode,

      email_subject:
        cleanText(row.email_subject),

      email_draft:
        cleanText(row.email_draft),

      linkedin_connection_note:
        cleanText(
          row.linkedin_connection_note
        ),

      linkedin_message:
        cleanText(row.linkedin_message),

      draft_final_status:
        draftFinalStatus,

      draft_generated_at:
        cleanText(row.draft_generated_at),

      sent_at:
        sentAt,

      follow_up_date:
        cleanText(row.follow_up_date),

      response_status:
        upper(row.response_status),

      follow_up_status:
        upper(row.follow_up_status),

      follow_up_draft:
        cleanText(row.follow_up_draft),

      follow_up_generated_at:
        cleanText(row.follow_up_generated_at),

      follow_up_approval:
        upper(row.follow_up_approval),

      follow_up_approved_at:
        cleanText(row.follow_up_approved_at),

      follow_up_sent_at:
        cleanText(row.follow_up_sent_at),

      follow_up_message_id:
        cleanText(row.follow_up_message_id),

      gmail_message_id:
        cleanText(row.gmail_message_id),

      gmail_thread_id:
        cleanText(row.gmail_thread_id),

      reply_detected_at:
        cleanText(row.reply_detected_at),

      reply_message_id:
        cleanText(row.reply_message_id),

      reply_from:
        cleanText(row.reply_from),

      reply_subject:
        cleanText(row.reply_subject),

      reply_snippet:
        cleanText(row.reply_snippet),

      notes:
        cleanText(row.notes),

      last_updated:
        cleanText(row.last_updated),

      can_send_email:
        canSendEmail,

      has_draft:
        Boolean(
          cleanText(row.email_draft) ||
          cleanText(row.linkedin_message)
        ),

      has_contact:
        Boolean(
          contactEmail ||
          cleanText(row.contact_linkedin_url)
        ),

      opportunity_type:
        opportunityType,
    };
  })
  .sort((first, second) => {
    const firstStatusOrder =
      applicationStatusOrder[
        first.application_status
      ] ?? 5;

    const secondStatusOrder =
      applicationStatusOrder[
        second.application_status
      ] ?? 5;

    if (firstStatusOrder !== secondStatusOrder) {
      return firstStatusOrder - secondStatusOrder;
    }

    return (
      second.qualification_score -
      first.qualification_score
    );
  });

return [
  {
    json: {
      success: true,

      count:
        opportunities.length,

      generated_at:
        new Date().toISOString(),

      summary: {
        to_review:
          opportunities.filter(
            item =>
              item.application_status ===
              'TO_REVIEW'
          ).length,

        applied:
          opportunities.filter(
            item =>
              item.application_status ===
              'APPLIED'
          ).length,

        skipped:
          opportunities.filter(
            item =>
              item.application_status ===
              'SKIPPED'
          ).length,

        drafts_ready:
          opportunities.filter(
            item => item.has_draft
          ).length,

        emails_sent:
          opportunities.filter(
            item => Boolean(item.sent_at)
          ).length,
      },

      opportunities,
    },
  },
];
